#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-16

# Test: the shipped container's Node major must match the one CI actually proves.
#
# The Dockerfile is a RELEASE ARTIFACT: release.yml builds and pushes it with
#   docker buildx build --platform linux/amd64,linux/arm64 --push .
# so a Node major that disagrees with .nvmrc means the published image runs a
# runtime nothing in CI ever tested. That is a silent divergence, not an outage,
# which is exactly why it survived #3473's unification of 26 of 31 call sites. (#3477)
#
# Three assertions, each independently load-bearing:
#   1. every `FROM node:<major>` equals the .nvmrc major
#   2. that major satisfies the root package.json `engines.node` range
#   3. the pin is a digest AND a bot is configured to bump it
#
# Assertion 3 exists because the Dockerfile's own comment claimed
# "Renovate/Dependabot bump it" while dependabot.yml had zero docker entries and
# no renovate.json existed. A pin nothing can bump is a pin that rots.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
DOCKERFILE="$REPO_ROOT/Dockerfile"
NVMRC="$REPO_ROOT/.nvmrc"
DEPENDABOT="$REPO_ROOT/.github/dependabot.yml"

FAILED=0
echo "=== Dockerfile Node Version Test ==="
echo ""

for f in "$DOCKERFILE" "$NVMRC"; do
    if [ ! -f "$f" ]; then
        echo "FAIL: missing required file: $f"
        exit 1
    fi
done

NVMRC_MAJOR="$(awk 'NR==1{sub(/^v/,""); split($0,a,"."); print a[1]}' "$NVMRC")"
echo "  .nvmrc major: $NVMRC_MAJOR"

# --- 1. FROM lines agree with .nvmrc ---------------------------------------
echo ""
echo "--- 1: every FROM node:<major> matches .nvmrc ---"
FROM_COUNT=0
while IFS= read -r major; do
    FROM_COUNT=$((FROM_COUNT + 1))
    if [ "$major" = "$NVMRC_MAJOR" ]; then
        echo "  PASS: FROM node:$major"
    else
        echo "  FAIL: FROM node:$major but .nvmrc says $NVMRC_MAJOR"
        FAILED=1
    fi
done < <(grep -oE '^FROM node:[0-9]+' "$DOCKERFILE" | grep -oE '[0-9]+$')

if [ "$FROM_COUNT" -eq 0 ]; then
    echo "  FAIL: no 'FROM node:<major>' line found in Dockerfile"
    FAILED=1
fi

# --- 2. that major satisfies root engines ----------------------------------
echo ""
echo "--- 2: the major satisfies root package.json engines.node ---"
ENGINES="$(python3 -c "
import json,pathlib
p=pathlib.Path('$REPO_ROOT/package.json')
print(json.loads(p.read_text()).get('engines',{}).get('node',''))
")"
echo "  engines.node: ${ENGINES:-<unset>}"
if [ -n "$ENGINES" ]; then
    if python3 -c "
import re,sys
spec='''$ENGINES'''
major=int('$NVMRC_MAJOR')
ok=True
for part in re.split(r'[,\s]+', spec.strip()):
    if not part: continue
    m=re.match(r'^(>=|<=|>|<|\^|~|=)?\s*v?(\d+)', part)
    if not m: continue
    op,v=m.group(1) or '=',int(m.group(2))
    if op=='>=' and not major>=v: ok=False
    elif op=='<=' and not major<=v: ok=False
    elif op=='>'  and not major>v:  ok=False
    elif op=='<'  and not major<v:  ok=False
    elif op in ('=','^','~') and major!=v: ok=False
sys.exit(0 if ok else 1)
"; then
        echo "  PASS: node $NVMRC_MAJOR satisfies '$ENGINES'"
    else
        echo "  FAIL: node $NVMRC_MAJOR does not satisfy '$ENGINES'"
        FAILED=1
    fi
else
    echo "  SKIP: root package.json declares no engines.node"
fi

# --- 3. digest-pinned AND a bot can bump it --------------------------------
echo ""
echo "--- 3: digest pin exists, and something is configured to bump it ---"
if grep -qE '^FROM node:[0-9]+-alpine@sha256:[0-9a-f]{64}' "$DOCKERFILE"; then
    echo "  PASS: FROM lines are digest-pinned"
else
    echo "  FAIL: FROM lines are not digest-pinned (Scorecard Pinned-Dependencies)"
    FAILED=1
fi

HAS_BUMPER=0
if [ -f "$DEPENDABOT" ] && grep -qE '^[[:space:]]*-?[[:space:]]*package-ecosystem:[[:space:]]*"?docker"?' "$DEPENDABOT"; then
    HAS_BUMPER=1
    echo "  PASS: dependabot.yml declares the docker ecosystem"
elif [ -f "$REPO_ROOT/renovate.json" ] || [ -f "$REPO_ROOT/.github/renovate.json" ]; then
    HAS_BUMPER=1
    echo "  PASS: renovate config present"
fi
if [ "$HAS_BUMPER" -eq 0 ]; then
    echo "  FAIL: nothing is configured to bump the digest."
    echo "        Add to .github/dependabot.yml:"
    echo "          - package-ecosystem: \"docker\""
    echo "            directory: \"/\""
    echo "            schedule: { interval: \"weekly\" }"
    FAILED=1
fi

echo ""
echo "=== Summary ==="
echo "  FROM node lines checked : $FROM_COUNT"
echo "  .nvmrc major            : $NVMRC_MAJOR"
echo ""

if [ "$FAILED" -ne 0 ]; then
    echo "RESULT: FAIL"
    echo ""
    echo "Refresh the digest with:  docker buildx imagetools inspect node:${NVMRC_MAJOR}-alpine"
    echo "and pin the top-level index digest so amd64 and arm64 both stay covered."
    exit 1
fi

echo "RESULT: PASS"
exit 0
